import hashlib, hmac, os

SECRET = os.environ['MP_WEBHOOK_SECRET']  # <<SUA_CHAVE_SECRETA_DE_WEBHOOK>>


def assinatura_valida(x_signature: str, x_request_id: str, data_id: str) -> bool:
    partes = dict(p.split('=', 1) for p in x_signature.split(','))
    ts, v1 = partes.get('ts', '').strip(), partes.get('v1', '').strip()
    manifesto = ''
    if data_id:
        manifesto += f'id:{data_id.lower()};'   # minúsculas quando vier alfanumérico (ORD...)
    if x_request_id:
        manifesto += f'request-id:{x_request_id};'
    if ts:
        manifesto += f'ts:{ts};'
    esperado = hmac.new(SECRET.encode(), manifesto.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(esperado, v1)


# No handler HTTP: valide, responda 200 na hora e só depois busque o recurso pela API.

const BASE = 'https://api.mercadopago.com';
const TOKEN = process.env.MP_ACCESS_TOKEN ?? '<<SEU_ACCESS_TOKEN>>';

async function todosOsPagamentos(dias = 30) {
  const itens: unknown[] = [];
  const limit = 100;
  for (let offset = 0; ; offset += limit) {
    const url = new URL(BASE + '/v1/payments/search');
    Object.entries({ sort: 'date_created', criteria: 'desc', range: 'date_created',
                     begin_date: `NOW-${dias}DAYS`, end_date: 'NOW',
                     offset: String(offset), limit: String(limit) })
      .forEach(([k, v]) => url.searchParams.set(k, v));
    const res = await fetch(url, { headers: { Authorization: `Bearer ${TOKEN}` } });
    if (res.status === 429) {                       // respeite o Retry-After
      await new Promise((r) => setTimeout(r, (Number(res.headers.get('Retry-After') ?? 5) + 1) * 1000));
      offset -= limit;
      continue;
    }
    if (!res.ok) throw new Error(`HTTP ${res.status} ${await res.text()}`);
    const { results = [] } = (await res.json()) as { results?: unknown[] };
    itens.push(...results);
    if (results.length < limit) break;              // página incompleta = fim
  }
  return itens;
}
